    idx = next(i for i,l in enumerate(lines) if l.strip().startswith('async fn '))
    pre = lines[:idx]
    sig_and_body = lines[idx:]
    # replace 'async fn NAME(' with 'pub(super) async fn NAME_impl(' and remove trailing ' &self,' param later
    # find and replace the ' &self,' first param
    sig_and_body = [l.replace('async fn ', 'pub(super) async fn ', 1) if i==0 else l for i,l in enumerate(sig_and_body)]
